-- Verify
SELECT cefr_level, count(*) FROM public.kelly_import_staging GROUP BY cefr_level ORDER BY cefr_level;
-- Match Kelly data to lexemes
UPDATE public.lexemes l
SET
  cefr_level    = k.cefr_level,
  frequency_rank = k.rank
FROM public.kelly_import_staging k
WHERE lower(l.lemma) = lower(k.lemma)
  AND k.cefr_level IS NOT NULL;

-- Also try stripping 'å ' prefix from verbs
-- Kelly sometimes lists verbs as "å gå" while lexemes has "gå"
UPDATE public.lexemes l
SET
  cefr_level    = k.cefr_level,
  frequency_rank = k.rank
FROM public.kelly_import_staging k
WHERE lower(l.lemma) = lower(regexp_replace(k.lemma, '^å\s+', ''))
  AND k.cefr_level IS NOT NULL
  AND l.cefr_level IS NULL;

-- Coverage check
SELECT
  l.pos,
  count(*) as total,
  count(l.cefr_level) as with_cefr,
  round(100.0 * count(l.cefr_level) / count(*), 1) as coverage_pct
FROM public.lexemes l
GROUP BY l.pos
ORDER BY total DESC;
